function SmithHammerHandleWedgeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SmithHammerHandleWedgeMaker.maker={name=n or ("Klinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klinar najet: %s (spretnost: %d)",SmithHammerHandleWedgeMaker.maker.name,s),"success") end; return true end
